// Decide whether the stored rows for this category are fresh enough to reuse.
const input = $('When Executed by Another Workflow').first().json;
const category = String(input.category || '').trim();
const force = input.force_refresh === true || input.force_refresh === 'true';

const DAY = 24 * 60 * 60 * 1000;
const now = Date.now();

// Keep only real rows (the empty item from "Always Output Data" has no tool_key)
const rows = $input.all().map(i => i.json).filter(r => r.tool_key);

// A row is fresh if its last_checked date is readable and at most 30 days old
const fresh = rows.filter(r => {
  const t = Date.parse(String(r.last_checked).slice(0, 10));
  return !Number.isNaN(t) && (now - t) <= 30 * DAY;
});

return [{ json: {
  category,
  force_refresh: force,
  total_rows: rows.length,
  fresh_rows: fresh.length,
  use_cache: !force && fresh.length >= 5,
  rows
}}];

const QUERIES = {
  crm: [
    'best CRM software for small businesses pricing per user per month',
    'CRM tools comparison free plan pricing small team',
    'top CRM software pricing plans starter'
  ],
  project_management: [
    'best project management software for small teams pricing per user',
    'project management tools comparison free plan pricing',
    'top project management apps pricing plans'
  ],
  email_marketing: [
    'best email marketing software for small businesses pricing',
    'email marketing tools comparison free plan pricing',
    'top email marketing platforms pricing plans'
  ]
};
const category = $json.category;
const list = QUERIES[category];
if (!list) throw new Error(`Unknown category: ${category}`);
return list.map(query => ({ json: { category, query } }));

// Did all 3 Tavily searches succeed with results?
// If any failed (after its retries) or nothing came back, send all 3 queries
// to the fallback provider instead (all-or-nothing: never mix two providers).
const tavily = $input.all();
const failed = tavily.filter(i => i.json.error || !Array.isArray(i.json.results));
const total = tavily.reduce((n, i) => n + (Array.isArray(i.json.results) ? i.json.results.length : 0), 0);

if (failed.length === 0 && total > 0) {
  return tavily.map(i => ({ json: { ...i.json, provider: 'tavily', use_fallback: false } }));
}

const err = failed.length ? failed[0].json.error : null;
const reason = !failed.length ? 'Tavily returned 0 results'
  : (typeof err === 'string' ? err : (err && err.message) || 'unexpected response from Tavily');

return $('Build queries').all().map(i => ({
  json: { ...i.json, use_fallback: true, tavily_error: reason }
}));

// Adapter: translate LangSearch's answer into Tavily's shape
// ({ results: [{ title, url, content }] }) so Combine pages works unchanged.
const out = $input.all().map(i => {
  const ok = !i.json.code || i.json.code === 200;            // LangSearch reports its own status in "code"
  const value = ok ? (i.json?.data?.webPages?.value || []) : [];
  return { json: {
    provider: 'langsearch',
    results: value.map(r => ({
      title: r.name || '',
      url: r.url || '',
      content: r.text || r.snippet || ''
    }))
  }};
});

const total = out.reduce((n, i) => n + i.json.results.length, 0);
if (total === 0) throw new Error('LangSearch fallback returned no usable results');
return out;

// Merge search results into one text chunk per query (3 smaller AI calls).
// v2: skips sources a human can't check against a live page (videos, archive copies, social posts).
// v2.1: host read with a regex, because URL() is not available in the n8n Code sandbox.
const BLOCKED = /(^|\.)(youtube\.com|youtu\.be|archive\.org|tiktok\.com|instagram\.com|facebook\.com)$/i;
const hostOf = u => {
  const m = String(u || '').match(/^https?:\/\/([^\/?#:]+)/i);   // text between "https://" and the next / ? # :
  return m ? m[1].toLowerCase() : '';
};

const seen = new Set();
const category = $('Build queries').first().json.category;
const provider = $input.first().json.provider || 'tavily';
const chunks = [];
let blocked = 0;

for (const item of $input.all()) {
  const parts = [];
  for (const r of (item.json.results || [])) {
    if (!r.url || seen.has(r.url)) continue;          // same page found twice
    seen.add(r.url);
    if (BLOCKED.test(hostOf(r.url))) { blocked++; continue; }   // unverifiable source
    parts.push(`URL: ${r.url}\nTITLE: ${r.title || ''}\nTEXT: ${String(r.content || '').slice(0, 1200)}`);
  }
  if (parts.length) chunks.push({ json: { category, provider, chunk: chunks.length + 1, blocked_so_far: blocked, pages: parts.join('\n\n---\n\n') } });
}

if (chunks.length === 0) throw new Error(`No usable search results for ${category} (provider: ${provider})`);
return chunks;

// ---------- inputs ----------
const items    = $input.all();                                   // one item per chunk
const category = items[0]?.json.category || $('Cache check').first().json.category;
const raw      = items.flatMap(i => i.json.tools || []);
const existing = $('Cache check').first().json.rows || [];       // what the sheet holds now
const today    = new Date().toISOString().slice(0, 10);          // YYYY-MM-DD

// ---------- helpers: messy value -> clean, typed value ----------
// Lists become "a, b, c"; null/undefined become ""; extra spaces removed.
const clean = v => (Array.isArray(v)
    ? v.map(x => String(x ?? '').trim()).filter(Boolean).join(', ')
    : String(v ?? ''))
  .replace(/\s+/g, ' ').trim();

// "HubSpot® CRM", "Hubspot", "Bigin by Zoho CRM", "Pipe Drive", "monday.com CRM"
//   -> "hubspot", "hubspot", "bigin", "pipedrive", "monday"
const normName = n => clean(n).toLowerCase()
  .replace(/[®™©]/g, '')
  .replace(/\.(com|io|ai|co|app)\b/g, ' ')
  .replace(/\b(crm|software|app|inc|ltd|the|platform)\b/g, ' ')
  .replace(/[^a-z0-9]+/g, ' ')
  .trim()
  .replace(/ by [a-z0-9]+$/, '')
  .trim();
const keyOf = n => normName(n).replace(/ /g, '');

// 15, "15", "€15/user/month", "15,00" -> 15 ; "Free" -> 0 ; "Contact sales", "", null -> null
const toNumber = v => {
  if (typeof v === 'number') return Number.isFinite(v) && v >= 0 ? Math.round(v * 100) / 100 : null;
  const s = clean(v).toLowerCase();
  if (!s || /contact|custom|quote|sales/.test(s)) return null;
  if (s === 'free') return 0;
  const m = s.replace(/\s/g, '').match(/(\d+(?:[.,]\d+)?)/);
  if (!m) return null;
  const n = parseFloat(m[1].replace(',', '.'));
  return Number.isFinite(n) && n >= 0 && n < 10000 ? Math.round(n * 100) / 100 : null;
};

// true, "yes", "oui", "1" -> true ; false, "no", "non", "0" -> false ; anything else -> null
const toBool = v => {
  if (typeof v === 'boolean') return v;
  const s = clean(v).toLowerCase();
  if (['true', 'yes', 'oui', '1'].includes(s)) return true;
  if (['false', 'no', 'non', '0'].includes(s)) return false;
  return null;
};

// Fix #5 v2: only USD, EUR, GBP are comparable; everything else -> null (price kept as a note).
const toCurrency = (c, note) => {
  const code = clean(c).toUpperCase();
  if (['USD', 'EUR', 'GBP'].includes(code)) return code;
  if (/^[A-Z]{3}$/.test(code)) return null;                       // another explicit code (INR, CAD…)
  const s = clean(note);
  if (/\b(INR|CAD|AUD|NZD|JPY|CHF|SEK|NOK|DKK|BRL|MXN|ZAR|SGD|HKD)\b|₹|\bRs\.?\s?\d|CA\$|C\$|AU?\$|NZ\$|S\$|HK\$|R\$|¥/i.test(s)) return null;
  if (/\bUSD\b|US\$|\$|\bdollars?\b/i.test(s)) return 'USD';
  if (/\bGBP\b|£|\bpounds?\b/i.test(s)) return 'GBP';
  if (/\bEUR\b|€|\beuros?\b/i.test(s)) return 'EUR';
  return null;
};

const isUrl  = u => /^https?:\/\/\S+$/i.test(clean(u));
// v2.1: regex instead of URL(), which is not available in the n8n Code sandbox
const hostOf = u => {
  const m = String(u || '').match(/^https?:\/\/([^\/?#:]+)/i);
  return m ? m[1].toLowerCase().replace(/^www\./, '') : '';
};
// Official source = the URL's host contains the tool's name (hubspot.com for HubSpot).
const official = (url, key) => key.length >= 4 && hostOf(url).replace(/[^a-z0-9]/g, '').includes(key.slice(0, 6));

// ---------- 1. clean every candidate, keep the best-sourced one per tool ----------
const best = new Map();                                   // tool_key -> { row, score, others }

for (const t of raw) {
  const name = clean(t.name);
  const k = keyOf(name);
  const url = clean(t.source_url);
  if (!name || !k || !isUrl(url)) continue;              // unusable row: rejected
  const tool_key = `${category}|${k}`;

  const cur = toCurrency(t.currency, t.price_note);
  const rawPrice = toNumber(t.price_per_user_month);
  const price = cur ? rawPrice : null;                   // no trusted currency -> no comparable price
  let note = clean(t.price_note);
  if (rawPrice !== null && !cur) note = `listed as ${rawPrice} ${clean(t.currency) || '(currency not stated)'}, see source`;
  if (price === null && !note) note = 'see source';
  const free = toBool(t.free_plan);

  const row = {
    tool_key,
    category,
    name: name.slice(0, 80),
    plan_name: clean(t.plan_name).slice(0, 60),
    price_per_user_month: price === null ? '' : price,
    currency: cur || '',
    price_note: note.slice(0, 120),
    free_plan: free === null ? '' : free,
    key_features: clean(t.key_features).slice(0, 200),
    integrations: clean(t.integrations).slice(0, 200),
    best_for: clean(t.best_for).slice(0, 120),
    source_url: url,
    last_checked: today,
  };

  const score = (official(url, k) ? 4 : 0) + (price !== null ? 3 : 0) + (row.plan_name ? 1 : 0)
              + (free !== null ? 1 : 0) + (row.key_features ? 1 : 0) + (row.integrations ? 1 : 0);

  const prev = best.get(tool_key);
  if (!prev) { best.set(tool_key, { row, score, others: [] }); continue; }

  const newWins = score > prev.score;
  const win  = newWins ? { row, score, others: prev.others } : prev;
  const lose = newWins ? prev.row : row;
  if (lose.price_per_user_month !== '' && lose.price_per_user_month !== win.row.price_per_user_month) {
    win.others.push(`${lose.price_per_user_month} ${lose.currency} (${hostOf(lose.source_url)})`);
  }
  best.set(tool_key, win);
}

// ---------- 2. protect human checks (v3) ----------
// A verified row keeps its human-checked values. If the refresh found a DIFFERENT
// non-empty value for one of the key fields, the row goes back to "unverified"
// and the note lists each change. An empty field from the refresh means
// "not found", not "changed".
const byKey  = new Map(existing.map(r => [r.tool_key, r]));
const FIELDS = ['price_per_user_month', 'currency', 'plan_name', 'free_plan'];
const norm   = v => String(v ?? '').replace(',', '.').trim().toLowerCase();
const show   = v => (norm(v) === '' ? '(empty)' : String(v));
const out = [];

for (const [tool_key, { row, others }] of best) {
  if (others.length) {
    row.price_note = `${row.price_note}${row.price_note ? '; ' : ''}also seen: ${[...new Set(others)].join(', ')}`.slice(0, 120);
  }

  const old = byKey.get(tool_key);

  if (old && old.status === 'verified') {
    const foundAt = hostOf(row.source_url);
    const changes = FIELDS
      .filter(f => norm(row[f]) !== '' && norm(row[f]) !== norm(old[f]))
      .map(f => `${f} ${show(old[f])} -> ${show(row[f])}`);

    // keep the human-checked values
    for (const f of [...FIELDS, 'price_note', 'source_url']) row[f] = old[f] ?? '';

    if (changes.length) {
      row.status = 'unverified';
      row.verified_by = '';
      row.notes = (`refresh on ${today} found: ${changes.join('; ')} (${foundAt}). Check, then /verify or edit.`
        + (old.notes ? ` | ${old.notes}` : '')).slice(0, 500);
    } else {
      row.status = 'verified';
      row.verified_by = old.verified_by || '';
      row.notes = old.notes || '';
    }
  } else {
    row.status = 'unverified';
    row.verified_by = '';
    row.notes = old ? (old.notes || '') : '';
  }

  out.push(row);
}

if (out.length === 0) throw new Error(`No valid tools extracted for ${category}`);
return out.map(r => ({ json: r }));

const items = $input.all();

// Cache branch: one item that carries the stored rows
if (items.length === 1 && Array.isArray(items[0].json.rows)) {
  return items[0].json.rows.map(r => ({ json: { ...r, from_cache: true } }));
}

// Search branch: the rows just saved, plus older stored rows this search did not find again
const saved = items.map(i => i.json);
const keys = new Set(saved.map(r => r.tool_key));
const older = ($('Cache check').first().json.rows || []).filter(r => !keys.has(r.tool_key));
return [
  ...saved.map(r => ({ json: { ...r, from_cache: false } })),
  ...older.map(r => ({ json: { ...r, from_cache: true } })),
];

// The search or the extraction failed even after retries: fall back to what we have.
const rows = $('Cache check').first().json.rows || [];
if (rows.length === 0) throw new Error('Search failed and there are no stored rows for this category');
return rows.map(r => ({ json: { ...r, from_cache: true, stale: true } }));
